export const verifiedQuestionCatalogVersion = "0.1.0+3bffbc48641d"
export const verifiedQuestionCatalog = [{"id":"offline-sync","category":"accounts-sync","question":"Can I use ProgressTracker without internet?","aliases":["What happens when I go offline?","Will my changes sync later?","Can I use this without internet?"],"keywords":["offline","local","sync","internet","device"],"suggestible":true,"sources":["src/db/localRepository.ts","src/services/supabase/syncEngine.ts","src/features/auth/AuthProvider.tsx"],"answer":"Tracker data is stored locally in the browser, so you can continue working while offline. Signed-in account data synchronizes when a connection is available again. Until then, changes on that device may not appear elsewhere."},{"id":"cross-device-sync","category":"accounts-sync","question":"Will my progress appear on another device?","aliases":["How do I sync trackers between devices?","Can I access my data on a new device?"],"keywords":["account","sign in","sync","devices","cloud"],"suggestible":true,"sources":["src/features/auth/AuthProvider.tsx","src/services/supabase/syncEngine.ts"],"answer":"Cross-device synchronization is available when you sign in to the same account and the devices are online. Guest data is stored locally on the device and does not automatically appear on another device."},{"id":"sync-conflicts","category":"accounts-sync","question":"What happens if two devices edit the same day?","aliases":["How does sync handle conflicting edits?","Will ProgressTracker merge two versions automatically?"],"keywords":["conflict","revision","sync","devices","edit"],"suggestible":true,"sources":["src/services/supabase/syncEngine.ts","src/db/syncConflictRepository.ts","src/db/syncConflictRepository.test.ts"],"answer":"When edits cannot be reconciled safely, sync records a conflict for you to resolve instead of silently combining incompatible versions. Review the conflict in the app’s sync/conflict flow; do not assume both edits were merged."},{"id":"account-signin","category":"accounts-sync","question":"How do I sign in or create an account?","aliases":["Can I sign in with an email link?","How do I register?"],"keywords":["sign in","create account","email link","password","authentication"],"suggestible":true,"sources":["src/features/auth/AuthPage.tsx","src/features/auth/authService.ts","src/features/auth/AuthPage.test.tsx"],"answer":"Use the account screen to request an email sign-in link or choose password sign-in. Choose Create account when registering a new account; using an email sign-in link for the first time creates an account for that email."},{"id":"workspace-backup","category":"accounts-sync","question":"Can I back up or restore my workspace data?","aliases":["How do I export my progress?","Can I import a workspace backup?"],"keywords":["backup","export","restore","JSON","workspace","sync conflicts"],"suggestible":true,"sources":["src/features/auth/WorkspaceBackup.tsx","src/db/workspaceBackup.ts","src/db/workspaceBackup.test.ts"],"answer":"Settings provides a local workspace backup you can download as JSON and restore into the same guest workspace or account. Restore previews changes, adds missing records, skips identical records, and stops if it finds a conflicting ID or date. Keep the backup file private."},{"id":"ai-help-private-data","category":"ai-help","question":"Can AI Help see my tracker entries?","aliases":["Does Groq receive my personal progress?","What data is sent when I ask a question?","Can AI Help read my check-in values?"],"keywords":["privacy","tracker entries","personal data","Groq","AI Help"],"suggestible":true,"sources":["src/features/ai-help/aiHelpService.ts","supabase/functions/ai-help/index.ts","supabase/functions/ai-help/assistantCore.ts"],"answer":"AI Help answers questions about how the product works; its request includes your question and limited conversation context, not your tracker entries. Do not include private tracker details in a question or support message."},{"id":"calendar-content","category":"calendar","question":"What does the calendar show?","aliases":["What do the calendar colors mean?","Can I see progress by date?"],"keywords":["calendar","activity","status","heatmap","date"],"suggestible":true,"sources":["src/features/calendar/CalendarPage.tsx","src/domain/trackers/activityHeatmap.ts"],"answer":"The calendar lets you navigate dates and review tracker activity for the selected period. Its activity indicators summarize saved progress; open a date to review or update the entries available for that day."},{"id":"skipped-vs-unchecked","category":"check-ins","question":"What is the difference between a skipped and unchecked day?","aliases":["Is skipping the same as leaving a day blank?","What does an unchecked date mean?","What is the difference between skipped and not checked?"],"keywords":["skipped","unchecked","absent","missing check-in","outcome"],"suggestible":true,"sources":["src/domain/trackers/missingCheckIns.ts","src/domain/trackers/types.ts","src/features/history/HistoryPage.tsx"],"answer":"A skipped day is an explicitly saved check-in marked as skipped. An unchecked date has no saved check-in. History can identify past missing opportunities from their schedule; a skipped entry is already a saved record and is not missing."},{"id":"edit-past-checkin","category":"check-ins","question":"Can I edit a past check-in?","aliases":["Can I change yesterday’s progress?","How do I correct an old entry?"],"keywords":["history","edit","past date","check-in","values"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/domain/trackers/progression.ts"],"answer":"Yes. Open History, select the saved date and tracker entry, then edit its values. The latest saved revision for that date is used in current calculations."},{"id":"clear-checkin","category":"check-ins","question":"What happens if I clear a check-in?","aliases":["Can I undo a check-in?","What happens if I clear yesterday’s progress?"],"keywords":["clear","delete","history","missing","re-record","check-in"],"suggestible":true,"sources":["src/features/shared/ClearCheckInAction.tsx","src/db/localRepository.ts","src/domain/trackers/missingCheckIns.ts"],"answer":"Clearing removes the saved check-in from current progress calculations. If that date was a past opportunity, it can then appear in missing check-in review. You can record the date again by creating a new check-in."},{"id":"numeric-zero-vs-empty","category":"check-ins","question":"Is entering zero different from leaving a number blank?","aliases":["Does zero count as no progress?","Is a blank quantity treated as zero?"],"keywords":["quantity","zero","blank","observation","numeric"],"suggestible":true,"sources":["src/domain/trackers/analytics.ts","src/features/shared/TrackerEntryFields.tsx","src/domain/trackers/schema.ts"],"answer":"Yes. Zero is a recorded numeric value and can be included in observations. A blank field is not a numeric observation. Whether a recorded zero qualifies as a successful check-in depends on the tracker’s success rules."},{"id":"mark-missed","category":"check-ins","question":"What happens when I mark a check-in as missed?","aliases":["Is marking a day missed different from leaving it blank?","Does Mark as missed break my streak?"],"keywords":["mark as missed","skipped","outcome","unchecked","streak"],"suggestible":true,"sources":["src/domain/trackers/types.ts","src/domain/trackers/progression.ts","src/features/today/TodayPage.tsx"],"answer":"Mark as missed saves an intentional skipped outcome for that date, and it breaks the streak. Leaving a date unchecked creates no saved entry; a past date can then appear in missing check-in review if it was an opportunity."},{"id":"custom-checkin-fields","category":"check-ins","question":"What are custom check-in fields?","aliases":["Can I add a note to a check-in?","Do notes count toward goal progress?"],"keywords":["notes","custom fields","context","measure","goal progress"],"suggestible":true,"sources":["src/features/trackers/TrackerConfigurationEditor.tsx","src/features/shared/TrackerEntryFields.tsx","src/domain/trackers/types.ts","src/features/shared/TrackerEntryFields.test.tsx"],"answer":"Custom check-in fields add context to an entry, such as a note or selected answer. They are separate from tracker measures and are not used as numeric goal totals."},{"id":"checkin-types","category":"check-ins","question":"What kinds of values can I record in a tracker?","aliases":["Can I track a number or a yes/no habit?","What measure types are available?"],"keywords":["Yes/No","quantity","measures","recorded values","legacy"],"suggestible":true,"sources":["src/domain/trackers/types.ts","src/features/trackers/trackerSetupSchema.ts","src/features/shared/TrackerEntryFields.tsx"],"answer":"New tracker measures use Yes/No or Quantity values. Existing trackers may also contain legacy measure types such as Duration or Checklist, which remain supported for their saved history."},{"id":"guest-mode","category":"getting-started","question":"Can I use ProgressTracker as a guest?","aliases":["Do I need an account to start tracking?","What happens to guest data?"],"keywords":["guest","account","local storage","sign in","tracker"],"suggestible":true,"sources":["src/features/auth/AuthProvider.tsx","src/db/localRepository.ts","src/features/auth/AuthPage.tsx","src/features/auth/AuthProvider.test.tsx"],"answer":"You can use ProgressTracker without signing in. Guest tracker data is stored locally in the browser on that device. Signing in enables account synchronization, but guest data does not automatically appear on another device."},{"id":"create-tracker","category":"getting-started","question":"How do I create a tracker?","aliases":["How do I start tracking a habit?","Where do I add a new tracker?"],"keywords":["create","setup","habit","goal","schedule","measure"],"suggestible":true,"sources":["src/features/trackers/TrackerSetupPage.tsx","src/features/trackers/TrackerSetupPage.test.tsx","src/features/trackers/trackerSetupSchema.ts"],"answer":"Open Trackers and choose Create tracker. Give it a name, choose the tracker kind and measures, then set its schedule and active dates. Save the form to begin using it. New measures support Yes/No or Quantity; some existing trackers can retain legacy measure types."},{"id":"daily-vs-cumulative-goal","category":"goals","question":"What is the difference between daily and cumulative goals?","aliases":["How does cumulative progress work?","Does my goal target reset every day?"],"keywords":["daily plan","cumulative plan","target","allocations","progress"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/domain/trackers/allocationPreview.ts","src/domain/trackers/goalPlanning.test.ts","src/features/goals/GoalsPage.tsx"],"answer":"A daily plan sets a target for each planned day. A cumulative plan sets a total amount to reach across its date range, with progress allocated across the plan. Which model applies depends on the saved goal plan."},{"id":"milestones","category":"goals","question":"How are milestones calculated?","aliases":["When is a milestone reached?","What does a linked milestone mean?"],"keywords":["goal","milestone","target","progress","linked measure"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/domain/trackers/allocationPreview.ts","src/features/goals/GoalsPage.tsx"],"answer":"A milestone is reached when the progress used by its linked goal plan meets the milestone target. The exact progress comes from that goal’s daily or cumulative plan and its eligible recorded values."},{"id":"goal-deadline","category":"goals","question":"Can a goal have a deadline?","aliases":["How does a goal deadline work?","What happens when a goal’s end date passes?"],"keywords":["goal","deadline","cumulative","active period","target"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/features/trackers/GoalPlanningEditor.tsx","src/domain/trackers/goalPlanning.test.ts"],"answer":"Yes. A goal can use a deadline to bound its planned date range, especially for cumulative targets. Progress and pacing are calculated within that plan period; dates after the tracker deadline are not included in its cumulative progress."},{"id":"complete-goal","category":"goals","question":"When is a goal complete?","aliases":["How do I know I reached my goal target?","Does reaching a milestone complete the goal?"],"keywords":["goal","completed","target","progress","milestone"],"suggestible":true,"sources":["src/features/goals/GoalsPage.tsx","src/domain/trackers/planning.ts","src/domain/trackers/goalPlanning.test.ts"],"answer":"The goal plan reports its target as complete when no planned work remains. The Goals page also shows the tracker’s saved status, so the displayed status can depend on both the goal state and plan. A milestone is a checkpoint within a plan; reaching one does not by itself mean the overall target is complete."},{"id":"history-includes","category":"history","question":"What does History include?","aliases":["What can I see in History?","Why does History not show every date?","Where can I review saved check-ins?"],"keywords":["saved entries","historical","holidays","missing check-ins","date","values"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/domain/trackers/missingCheckIns.ts","src/features/history/HistoryPage.test.tsx"],"answer":"History shows saved check-ins and their recorded values for past dates, along with workspace holidays in the selected date range. It also offers a missing check-in review for unresolved opportunities in the previous seven completed days. Dates that were not tracking opportunities are not shown as missing, and today is not treated as overdue."},{"id":"missing-checkins","category":"history","question":"Where can I find missing check-ins?","aliases":["How do I review missed days?","Can I find dates I forgot to log?","Where do I review missed check-ins?"],"keywords":["missing","overdue","history","schedule","past opportunity"],"suggestible":true,"sources":["src/features/history/HistoryPage.tsx","src/domain/trackers/missingCheckIns.ts"],"answer":"Open History and review its missing check-in section. It lists past unresolved opportunities for active trackers, based on each tracker’s active dates, schedule, Strict Mode, and workspace holidays. It does not list today as missing."},{"id":"create-holiday","category":"holidays","question":"How do I add a holiday?","aliases":["Can I mark a day as a break?","How do I add a retroactive holiday?"],"keywords":["holiday","break","date","reason","workspace"],"suggestible":true,"sources":["src/features/holidays/HolidaysPage.tsx","src/domain/holidays.ts","src/domain/holidays.test.ts"],"answer":"Open Holidays & breaks, choose a date, and save the holiday. You can add a reason and choose a past date; holidays apply across the workspace rather than to only one tracker."},{"id":"delete-holiday","category":"holidays","question":"What happens if I delete a holiday?","aliases":["Does removing a holiday change saved check-ins?","Can I undo a workspace break?"],"keywords":["holiday","delete","saved check-in","schedule","history"],"suggestible":true,"sources":["src/features/holidays/HolidaysPage.tsx","src/domain/holidays.ts"],"answer":"Deleting a holiday removes that date’s break from future calculations. Any check-ins already saved for the date remain saved; changing the holiday does not erase them."},{"id":"holidays-streaks","category":"holidays","question":"Do holidays count against my streak?","aliases":["How do holidays affect scheduled check-ins?","Does a holiday pause my tracker?","Do holidays count against my streak?"],"keywords":["holiday","streak","scheduled","strict mode","recorded entry"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/planning.ts","src/domain/holidays.ts"],"answer":"In Standard Mode, a holiday removes that date from scheduled streak opportunities. In Strict Mode, dates remain daily opportunities, so a holiday by itself does not excuse a missed day. A saved qualifying check-in on a holiday still counts in Strict Mode."},{"id":"reminder-limits","category":"notifications","question":"Do reminders arrive when the app is closed?","aliases":["Are reminders sent in the background?","Why did I not get a push notification?"],"keywords":["notification","reminder","foreground","background","push"],"suggestible":true,"sources":["src/features/notifications/ForegroundReminderMonitor.tsx","src/features/notifications/capabilities.ts"],"answer":"The current reminder monitor works while the app is open in the foreground. Background delivery depends on separate push delivery setup, so browser permission alone does not guarantee a reminder when the app is closed."},{"id":"notification-preferences","category":"notifications","question":"Where can I change notification preferences?","aliases":["How do I turn reminders on or off?","Can I change reminder settings?"],"keywords":["reminders","notifications","settings","browser permission"],"suggestible":true,"sources":["src/features/notifications/NotificationsSettings.tsx","src/features/notifications/capabilities.ts","src/features/notifications/NotificationsSettings.test.tsx"],"answer":"Open Settings and find Notifications to review the available reminder preferences and device permission status. Available controls depend on browser and device support."},{"id":"missing-checkin-reminder","category":"notifications","question":"How does the missing check-in reminder work?","aliases":["Why does Today show a missing check-in reminder?","When are overdue check-ins highlighted?"],"keywords":["Today","missing check-in","overdue","reminder","schedule"],"suggestible":true,"sources":["src/features/today/TodayPage.tsx","src/features/notifications/reminderRules.ts","src/features/notifications/ForegroundReminderMonitor.tsx","src/features/notifications/reminderRules.test.ts"],"answer":"The app can highlight unresolved check-in opportunities in its foreground experience, and History reviews missing opportunities from the previous seven completed days. These reminders depend on tracker schedules and active dates; they do not mean a saved check-in was deleted."},{"id":"local-settings","category":"settings-privacy","question":"Do my appearance and time zone settings sync?","aliases":["Will dark mode carry to another device?","Does changing my time zone sync to my account?"],"keywords":["appearance","time zone","settings","local","sync"],"suggestible":true,"sources":["src/features/settings/appearance.ts","src/features/settings/WorkspaceTimeZone.tsx","src/services/supabase/syncEngine.ts","src/features/settings/appearance.test.ts","src/features/settings/WorkspaceAppearance.test.tsx"],"answer":"Appearance and workspace time-zone preferences are stored locally and are not part of the account records synchronized between devices. Set them separately on each device where you use the app."},{"id":"timezone-dates","category":"settings-privacy","question":"Do check-in dates change when I change my time zone?","aliases":["Will my old entries move to a different day?","How does the workspace time zone affect tracking?"],"keywords":["time zone","calendar date","historical","check-in","local date"],"suggestible":true,"sources":["src/features/settings/WorkspaceTimeZone.tsx","src/db/calendarDate.ts","src/db/calendarDate.test.ts"],"answer":"Check-ins are stored by calendar date, so changing the workspace time zone does not shift already saved entries to another day. The selected time zone affects how dates and new daily boundaries are interpreted."},{"id":"completion-rate","category":"statistics","question":"How is completion rate calculated?","aliases":["How do you calculate my completion percentage?","Why is my completion rate lower than expected?","What is the denominator for completion rate?"],"keywords":["percentage","consistency","scheduled opportunities","qualifying entries","denominator","analytics"],"suggestible":true,"sources":["src/domain/trackers/analytics.ts","src/domain/trackers/planning.ts","src/domain/trackers/progression.ts","src/domain/trackers/analytics.test.ts"],"answer":"For an active tracker with scheduled opportunities, the consistency percentage is the number of qualifying opportunities divided by the number of counted opportunities, rounded to a whole percent. Standard Mode counts scheduled dates except holidays; Strict Mode counts every active date, including otherwise unscheduled dates and holidays. The current as-of date is left out when it has no entry yet. If there are no counted opportunities, the percentage is unavailable."},{"id":"qualifying-checkin","category":"statistics","question":"What makes a check-in count as successful?","aliases":["What counts as a completed day?","Why did my check-in not count toward progress?"],"keywords":["success rule","threshold","qualifying","recorded","outcome","measure"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/planning.ts","src/domain/trackers/types.ts"],"answer":"A recorded check-in qualifies when its outcome and values meet the tracker’s configured success rules. A tracker can have multiple measures and rules, so recording something does not always mean the day qualifies. A skipped check-in is not a qualifying recorded result."},{"id":"points-and-rewards","category":"statistics","question":"How do achievement points and streak rewards work?","aliases":["Do I lose reward points if my streak resets?","What earns points in Achievements?"],"keywords":["achievements","points","reward","qualified check-in","milestone","longest streak"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/features/dashboard/AchievementsPage.tsx"],"answer":"Each qualifying check-in earns points, and reaching a new longest-streak milestone earns additional points. A missed day can end the current streak, but it does not subtract points already earned. Achievements are calculated from the tracker’s saved history, so editing or clearing history can recalculate the totals."},{"id":"standard-vs-strict","category":"streaks","question":"What is the difference between Standard Mode and Strict Mode?","aliases":["Does Strict Mode count rest days?","Which days become opportunities in Strict Mode?"],"keywords":["Standard Mode","Strict Mode","schedule","daily","opportunity","holidays"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/analytics.ts","src/features/trackers/TrackerConfigurationEditor.tsx"],"answer":"Standard Mode counts the tracker’s scheduled dates as opportunities and pauses over unscheduled days and holidays. Strict Mode counts every date in the active period, including unscheduled dates and holidays. A saved qualifying check-in on a holiday can still count in either mode."},{"id":"streak-statistics","category":"streaks","question":"How do streak statistics work?","aliases":["How are streaks calculated?","What counts toward my current streak?","Why did my streak reset?"],"keywords":["current streak","longest streak","qualifying check-in","schedule","strict mode","rest day","holiday"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/planning.ts","src/domain/trackers/progression.test.ts"],"answer":"Your current streak is the run of recent tracking opportunities you have met. Your longest streak is the best qualifying run in the tracker’s history. A missed required opportunity can end the current run, while the longest record remains. Which dates count depends on the tracker’s schedule, Strict Mode, and holidays."},{"id":"rest-days-streaks","category":"streaks","question":"How do rest days affect streaks?","aliases":["Do unscheduled days break a streak?","Does my schedule pause my streak?"],"keywords":["schedule","unscheduled","opportunity","strict mode","rest day"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/planning.ts"],"answer":"In Standard Mode, only scheduled check-in dates are opportunities, so unscheduled rest days do not break a streak. Strict Mode treats every active date as an opportunity, including dates outside the regular schedule. Tracker start and deadline dates still bound the active period."},{"id":"streak-longest","category":"streaks","question":"What is the difference between my current streak and longest streak?","aliases":["Does losing my streak erase my record?","Why is my longest streak higher than my current streak?"],"keywords":["current streak","longest streak","record","history"],"suggestible":true,"sources":["src/domain/trackers/progression.ts","src/domain/trackers/progression.test.ts"],"answer":"Your current streak describes your ongoing qualifying run. Your longest streak is the best qualifying run found in the tracker’s history, so a current streak ending does not erase that record."},{"id":"restore-deleted-tracker","category":"trackers","question":"Can I restore a deleted tracker?","aliases":["Where do deleted trackers go?","How do I recover a tracker from the Bin?"],"keywords":["Bin","restore","deleted tracker","archive","recover"],"suggestible":true,"sources":["src/features/trackers/TrackerBinPage.tsx","src/features/trackers/TrackerLibraryPage.tsx","src/features/trackers/TrackerBinPage.test.tsx"],"answer":"Trackers deleted through the tracker flow appear in The Bin, where you can choose Restore. Archiving or pausing a tracker is different: it stays in your tracker library and keeps its history."},{"id":"bin-retention","category":"trackers","question":"What happens to a tracker after I delete it?","aliases":["Is a deleted tracker erased immediately?","How long can I restore something from The Bin?"],"keywords":["delete","Bin","soft delete","restore","retention","permanent deletion"],"suggestible":false,"sources":["src/features/trackers/TrackerBinPage.tsx","src/db/localRepository.ts"],"answer":"Deleting a tracker moves it to The Bin, where it can be restored for 30 days with its saved progress and plan. Permanent deletion is disabled in this app build, so a tracker in The Bin is retained rather than immediately erased."},{"id":"edit-tracker-history","category":"trackers","question":"Do tracker edits change historical statistics?","aliases":["What happens to old stats when I edit a tracker?","Can changing a measure change old entries?"],"keywords":["edit","historical","measure type","schedule","statistics"],"suggestible":true,"sources":["src/domain/trackers/invariants.ts","src/features/trackers/TrackerConfigurationEditor.tsx","src/domain/trackers/analytics.ts"],"answer":"Some edits can change which dates count in schedule-based statistics, because calculations use the tracker’s current schedule and active period. A saved measure’s type and historical interpretation are protected. Retiring a measure removes it from future check-ins while retaining its definition for old entries."},{"id":"archive-tracker","category":"trackers","question":"What happens when I archive a tracker?","aliases":["Does archiving delete my tracker history?","Can I restore a paused tracker?"],"keywords":["archive","pause","active","history","delete"],"suggestible":true,"sources":["src/features/trackers/TrackerLibraryPage.tsx","src/features/trackers/TrackerBinPage.tsx"],"answer":"Archiving or pausing a tracker stops it being active for future opportunities but keeps its recorded history. Deleting a tracker is a separate action that moves it through the app’s Bin and restore flow."},{"id":"tracker-schedules","category":"trackers","question":"How do tracker schedules work?","aliases":["Which days count as scheduled?","How do I choose tracking days?"],"keywords":["schedule","weekly","daily","weekdays","opportunity"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/features/trackers/TrackerSetupPage.tsx"],"answer":"The schedule defines the regular days when a tracker has a check-in opportunity. You choose it while creating or editing a tracker. Standard Mode uses those scheduled dates for streak and consistency opportunities; Strict Mode treats every active date as an opportunity."},{"id":"start-date-deadline","category":"trackers","question":"How do a tracker’s start date and deadline affect it?","aliases":["When does a tracker begin counting?","Does a deadline stop future check-ins?"],"keywords":["start date","deadline","active period","schedule","tracker"],"suggestible":true,"sources":["src/domain/trackers/planning.ts","src/domain/trackers/activePeriod.test.ts","src/domain/trackers/planning.test.ts","src/features/trackers/TrackerSetupPage.tsx"],"answer":"The tracker’s active period is bounded by its start date and, when set, its deadline. Dates outside that period are not active tracking opportunities. A deadline therefore stops schedule-based calculations from counting later dates."},{"id":"retire-measure","category":"trackers","question":"What happens when I retire a measure?","aliases":["Can I remove a measure but keep its history?","Why is an old measure still shown in History?"],"keywords":["retire","measure","old entries","history","future check-ins"],"suggestible":true,"sources":["src/features/trackers/TrackerConfigurationEditor.tsx","src/domain/trackers/types.ts","src/domain/trackers/schema.test.ts","src/features/history/HistoryPage.tsx"],"answer":"Retiring a measure removes it from future check-ins while keeping its definition available to interpret older entries. That is why an old measure may still appear when you review historical data."},{"id":"tracker-editing","category":"trackers","question":"How do I edit a tracker?","aliases":["Where can I change a tracker’s schedule?","Can I add another measure to a tracker?"],"keywords":["edit","tracker","schedule","measures","configuration"],"suggestible":true,"sources":["src/features/trackers/TrackerLibraryPage.tsx","src/features/trackers/TrackerConfigurationEditor.tsx","src/features/trackers/TrackerSetupPage.tsx","src/features/trackers/TrackerSetupPage.test.tsx"],"answer":"Open Trackers, choose the tracker’s edit action, update its supported settings, then save. You can change configuration such as its schedule and add measures, while saved measure types and their historical meaning are protected."}] as const
